"use client";

import { AuthGuard } from "@/components/auth/AuthGuard";
import { AdminShell } from "@/components/layout/AdminShell";
import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
import { MetricCards } from "@/components/dashboard/MetricCards";
import { RecentActivity } from "@/components/dashboard/RecentActivity";
import { RiskSummary } from "@/components/dashboard/RiskSummary";
import { BottomStats } from "@/components/dashboard/BottomStats";

export default function AdminDashboardPage() {
  return (
    <AuthGuard>
      <AdminShell>
        <DashboardHeader />
        <main className="flex flex-1 flex-col gap-4 overflow-y-auto px-5 py-5 md:px-7 md:py-6">
          <MetricCards />
          <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1.55fr)_minmax(280px,0.85fr)]">
            <RecentActivity />
            <RiskSummary />
          </div>
          <BottomStats />
        </main>
      </AdminShell>
    </AuthGuard>
  );
}
