const METRICS = [
  {
    title: "PENDING DEPOSITS",
    value: "128",
    sub: "Awaiting review",
    delta: "+12% vs last hour",
    deltaTone: "up" as const,
    icon: "inbox" as const,
    spark: "gold" as const,
    points: "2,18 10,14 18,15 26,10 34,12 42,7 50,9",
  },
  {
    title: "LIVE PLAYERS",
    value: "342",
    sub: "Online now",
    delta: "+8% vs last 15 min",
    deltaTone: "up" as const,
    icon: "users" as const,
    spark: "green" as const,
    points: "2,16 10,13 18,14 26,9 34,11 42,6 50,8",
  },
  {
    title: "TODAY HANDLE",
    value: "$2,845,760",
    sub: "Total wagered",
    delta: "+18% vs yesterday",
    deltaTone: "up" as const,
    icon: "coins" as const,
    spark: "gold" as const,
    points: "2,17 10,15 18,12 26,13 34,8 42,9 50,5",
  },
  {
    title: "TODAY WIN / LOSS",
    value: "$186,540",
    sub: "House result",
    delta: "6.55% Win Rate",
    deltaTone: "neutral" as const,
    icon: "trophy" as const,
    spark: "gold" as const,
    points: "2,14 10,15 18,11 26,12 34,9 42,10 50,7",
  },
  {
    title: "RISK FLAGS",
    value: "23",
    sub: "Open alerts",
    delta: "+5 since last hour",
    deltaTone: "down" as const,
    icon: "flag" as const,
    spark: "red" as const,
    points: "2,8 10,10 18,9 26,13 34,12 42,16 50,14",
  },
  {
    title: "USD BALANCE",
    value: "$1,234,567",
    sub: "Treasury",
    delta: "+2.3% vs yesterday",
    deltaTone: "up" as const,
    icon: "wallet" as const,
    spark: "gold" as const,
    points: "2,15 10,14 18,12 26,11 34,10 42,8 50,7",
  },
] as const;

const SPARK_COLOR = {
  gold: "#d4af37",
  green: "#2ecc71",
  red: "#e74c3c",
} as const;

export function MetricCards() {
  return (
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6">
      {METRICS.map((m) => (
        <article
          key={m.title}
          className="sd-dash-card rounded-xl border border-[#2f291c] bg-[#101010] p-3.5"
        >
          <div className="mb-2 flex items-start justify-between gap-2">
            <p className="text-[0.58rem] font-semibold tracking-[0.14em] text-[#8a8070]">
              {m.title}
            </p>
            <span className="flex size-7 items-center justify-center rounded-full border border-[#d4af37]/35 bg-[#1a160c] text-[#e8c547]">
              <MetricIcon name={m.icon} />
            </span>
          </div>
          <p className="font-[family-name:var(--font-cinzel)] text-[1.35rem] font-semibold leading-none tracking-wide text-[#f5efe0]">
            {m.value}
          </p>
          <p className="mt-1.5 text-[0.68rem] text-[#8a8070]">{m.sub}</p>
          <p
            className={`mt-1 text-[0.68rem] font-semibold ${
              m.deltaTone === "down"
                ? "text-[#e74c3c]"
                : m.deltaTone === "up"
                  ? "text-[#2ecc71]"
                  : "text-[#d4af37]"
            }`}
          >
            {m.delta}
          </p>
          <svg
            className="mt-2 w-full"
            viewBox="0 0 52 20"
            height="28"
            preserveAspectRatio="none"
            aria-hidden
          >
            <polyline
              fill="none"
              stroke={SPARK_COLOR[m.spark]}
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
              points={m.points}
              opacity="0.9"
            />
          </svg>
        </article>
      ))}
    </div>
  );
}

function MetricIcon({ name }: { name: (typeof METRICS)[number]["icon"] }) {
  const common = {
    width: 14,
    height: 14,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.7,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    "aria-hidden": true as const,
  };
  if (name === "inbox") {
    return (
      <svg {...common}>
        <path d="M4 8h16v10a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8Z" />
        <path d="M4 12h4.5l1.5 2h4l1.5-2H20" />
        <path d="m8 8 4-4 4 4" />
      </svg>
    );
  }
  if (name === "users") {
    return (
      <svg {...common}>
        <circle cx="9" cy="8" r="3" />
        <path d="M3.5 19c1.2-3 3.2-4.5 5.5-4.5S13.3 16 14.5 19" />
        <circle cx="16.5" cy="9" r="2.3" />
      </svg>
    );
  }
  if (name === "coins") {
    return (
      <svg {...common}>
        <ellipse cx="12" cy="7" rx="7" ry="3" />
        <path d="M5 7v5c0 1.7 3.1 3 7 3s7-1.3 7-3V7" />
        <path d="M5 12v5c0 1.7 3.1 3 7 3s7-1.3 7-3v-5" />
      </svg>
    );
  }
  if (name === "trophy") {
    return (
      <svg {...common}>
        <path d="M8 4h8v4a4 4 0 0 1-8 0V4Z" />
        <path d="M8 6H5.5A2 2 0 0 0 7.2 9.5M16 6h2.5A2 2 0 0 1 16.8 9.5" />
        <path d="M10 18h4M12 12v6M9 21h6" />
      </svg>
    );
  }
  if (name === "flag") {
    return (
      <svg {...common}>
        <path d="M6 21V4" />
        <path d="M6 5h10l-2 3.5L16 12H6" />
      </svg>
    );
  }
  return (
    <svg {...common}>
      <rect x="3" y="6" width="18" height="13" rx="2" />
      <path d="M3 10h18" />
      <path d="M8 15h3" />
    </svg>
  );
}
